def copiar_cotizaciones(apps, schema_editor):
    """HU 28: las cotizaciones que ya existían pasan a ser consultas.

    El estado viejo "Respondida" queda como "Contactada".
    """
    SolicitudCotizacion = apps.get_model("cotizaciones", "SolicitudCotizacion")
    Consulta = apps.get_model("consultas", "Consulta")
    Pedido = apps.get_model("pedidos", "Pedido")
    for s in SolicitudCotizacion.objects.all():
        respondida = getattr(s, "estado", "nueva") == "respondida"
        # Si después de la cotización esa persona ya hizo un pedido, la consulta queda en "Compró"
        pedido = Pedido.objects.filter(creado__gte=s.fecha).filter(
            models.Q(cotizacion_id=s.pk) | models.Q(correo__iexact=s.correo or "-") | models.Q(telefono=s.whatsapp)
        ).order_by("creado").first()
        if pedido:
            estado = "compro"
        else:
            estado = "contactada" if respondida else "nueva"
        Consulta.objects.create(
            origen="cotizacion", cotizacion=s, producto_id=s.producto_id, nombre=s.nombre,
            whatsapp=s.whatsapp, correo=s.correo, mensaje=s.descripcion or s.motivo, fecha=s.fecha,
            estado=estado, contactada_en=s.fecha if respondida else None,
            compro_en=pedido.creado if pedido else None, pedido=pedido,
        )


